<template>
<div class="connectivity">
<header class="top"><div><h1>Network Connectivity & Cable Tracing</h1><p>Document provider fibre, routers, firewalls, switch uplinks, ODFs and patch leads.</p></div><NuxtLink class="btn secondary-btn" to="/racks">Open racks</NuxtLink></header>
<p v-if="error" class="panel warning" role="alert">{{error}}</p><p v-if="notice" class="panel ok">{{notice}}</p>
<section class="panel toolbar"><label>Building<select v-model="buildingId"><option value="">Choose building…</option><option v-for="b in buildings" :key="b.id" :value="b.id">{{b.name}}</option></select></label><button class="btn secondary-btn" @click="reload">Refresh</button></section>
<template v-if="buildingId">
<div class="twocol">
<section class="panel"><h2>Network equipment</h2><p class="hint">Routers, firewalls, provider NTDs, optical distribution frames and media converters.</p>
<form v-if="isAdmin" class="formgrid" @submit.prevent="saveEquipment"><label>Name<input v-model="equipmentForm.name" required maxlength="120" placeholder="Edge Router 01"></label><label>Type<select v-model="equipmentForm.kind"><option v-for="k in equipmentKinds" :key="k" :value="k">{{k}}</option></select></label><label>Manufacturer<input v-model="equipmentForm.manufacturer" maxlength="120"></label><label>Model<input v-model="equipmentForm.model" maxlength="120"></label><label>Management IP<input v-model="equipmentForm.management_ip" maxlength="80"></label><label>Notes<input v-model="equipmentForm.notes" maxlength="500"></label><div class="actions"><button class="btn" :disabled="busy">{{equipmentForm.id?'Update equipment':'Add equipment'}}</button><button v-if="equipmentForm.id" type="button" class="btn secondary-btn" @click="equipmentForm=blankEquipment()">Cancel</button></div></form>
<div v-for="e in localEquipment" :key="e.id" class="record"><strong>{{e.name}}</strong><span>{{e.kind}} · {{e.manufacturer}} {{e.model}}</span><button v-if="isAdmin" class="small-btn" @click="equipmentForm={...e}">Edit</button><button v-if="isAdmin" class="small-btn" @click="removeEquipment(e)">Delete</button></div></section>
<section class="panel"><h2>Provider circuits</h2><p class="hint">Record the incoming service and create a provider handoff endpoint below.</p>
<form v-if="isAdmin" class="formgrid" @submit.prevent="saveCircuit"><label>Provider<input v-model="circuitForm.provider" required maxlength="120" placeholder="Internet provider"></label><label>Circuit ID<input v-model="circuitForm.circuit_id" maxlength="120"></label><label>Service<select v-model="circuitForm.service_type"><option>fibre</option><option>ethernet</option><option>copper</option><option>other</option></select></label><label>Handoff<input v-model="circuitForm.handoff" placeholder="LC duplex / RJ45" maxlength="120"></label><label class="wide">Notes<input v-model="circuitForm.notes" maxlength="500"></label><div class="actions"><button class="btn" :disabled="busy">{{circuitForm.id?'Update circuit':'Add circuit'}}</button><button v-if="circuitForm.id" type="button" class="btn secondary-btn" @click="circuitForm=blankCircuit()">Cancel</button></div></form>
<div v-for="c in localCircuits" :key="c.id" class="record"><strong>{{c.provider}}</strong><span>{{c.circuit_id||'No circuit ID'}} · {{c.service_type}} · {{c.handoff}}</span><button v-if="isAdmin" class="small-btn" @click="circuitForm={...c}">Edit</button><button v-if="isAdmin" class="small-btn" @click="removeCircuit(c)">Delete</button></div></section>
</div>
<section class="panel"><h2>Physical port endpoints</h2><p class="hint">Register the specific ports used in links. For patch panels, use <strong>front:12</strong> for the patch-lead side; existing permanent cabling remains documented on the rear. Switch port keys can be e.g. <strong>Slot A / 12</strong>.</p>
<form v-if="isAdmin" class="endpoint-form" @submit.prevent="saveEndpoint"><label>Device type<select v-model="endpointForm.endpoint_type" @change="endpointForm.ref_id=''" required><option v-for="t in endpointTypes" :key="t.value" :value="t.value">{{t.label}}</option></select></label><label>Device<select v-model="endpointForm.ref_id" required><option value="">Choose device…</option><option v-for="d in availableDevices(endpointForm.endpoint_type)" :key="d.id" :value="d.id">{{d.name}}</option></select></label><label>Port / socket identifier<input v-model="endpointForm.port_key" required maxlength="80" placeholder="WAN1 / SFP1 / front:12"></label><label>Connector<select v-model="endpointForm.connector"><option>RJ45</option><option>LC duplex</option><option>LC simplex</option><option>SC</option><option>MPO</option><option>QSFP</option><option>DAC</option><option>Other</option></select></label><label>Notes<input v-model="endpointForm.notes" maxlength="500"></label><button class="btn" :disabled="busy||!endpointForm.ref_id">{{endpointForm.id?'Update endpoint':'Add endpoint'}}</button><button v-if="endpointForm.id" type="button" class="btn secondary-btn" @click="endpointForm=blankEndpoint()">Cancel</button></form>
<div class="scroll"><table><thead><tr><th>Device</th><th>Port</th><th>Connector</th><th>Link</th><th></th></tr></thead><tbody><tr v-for="e in localEndpoints" :key="e.id"><td>{{endpointLabel(e)}}</td><td>{{e.port_key}}</td><td>{{e.connector}}</td><td>{{linked(e.id)?'Connected':'Available'}}</td><td><button v-if="isAdmin" class="small-btn" @click="endpointForm={...e}">Edit</button> <button v-if="isAdmin" class="small-btn" @click="removeEndpoint(e)">Delete</button></td></tr></tbody></table></div></section>
<section class="panel"><h2>Physical cable links</h2><p class="hint">Create direct copper, fibre, DAC or provider-handoff connections. Each physical endpoint can be used by one cable only.</p>
<form v-if="isAdmin" class="link-form" @submit.prevent="saveLink"><label>Endpoint A<select v-model="linkForm.a_id" required><option value="">Choose…</option><option v-for="e in localEndpoints" :key="e.id" :value="e.id" :disabled="linked(e.id,linkForm.id)">{{endpointLabel(e)}} — {{e.port_key}}</option></select></label><label>Endpoint B<select v-model="linkForm.b_id" required><option value="">Choose…</option><option v-for="e in localEndpoints" :key="e.id" :value="e.id" :disabled="e.id===linkForm.a_id||linked(e.id,linkForm.id)">{{endpointLabel(e)}} — {{e.port_key}}</option></select></label><label>Connection type<select v-model="linkForm.connection_kind"><option value="patch_lead">Patch lead</option><option value="backbone">Backbone</option><option value="provider_handoff">Provider handoff</option><option value="direct">Direct link</option><option value="other">Other</option></select></label><label>Cable medium<select v-model="linkForm.medium"><option v-for="m in media" :key="m" :value="m">{{m.toUpperCase()}}</option></select></label><label>Cable ID<input v-model="linkForm.cable_id" maxlength="120"></label><label>Connector<input v-model="linkForm.connector" maxlength="120" placeholder="LC duplex"></label><label>Fibre cores<input v-model="linkForm.fibre_cores" maxlength="120" placeholder="1–2"></label><label>Notes<input v-model="linkForm.notes" maxlength="500"></label><div class="actions"><button class="btn" :disabled="busy||!linkForm.a_id||!linkForm.b_id||linkForm.a_id===linkForm.b_id">{{linkForm.id?'Update link':'Create link'}}</button><button v-if="linkForm.id" type="button" class="btn secondary-btn" @click="linkForm=blankLink()">Cancel</button></div></form>
<div class="scroll"><table><thead><tr><th>From</th><th>To</th><th>Medium</th><th>Cable ID</th><th></th></tr></thead><tbody><tr v-for="l in localLinks" :key="l.id"><td>{{endpointText(l.a_id)}}</td><td>{{endpointText(l.b_id)}}</td><td>{{l.medium}} · {{l.connection_kind}}</td><td>{{l.cable_id||'—'}}</td><td><button v-if="isAdmin" class="small-btn" @click="linkForm={...l}">Edit</button> <button v-if="isAdmin" class="small-btn" @click="removeLink(l)">Delete</button></td></tr></tbody></table></div></section>
<section class="panel"><h2>End-to-end physical trace</h2><p class="hint">Select a port to trace both directions through recorded links. Existing patch-panel-to-outlet permanent cables are included.</p><div class="trace-tools"><label>Starting endpoint<select v-model="traceStart"><option value="">Choose endpoint…</option><option v-for="e in localEndpoints" :key="e.id" :value="e.id">{{endpointLabel(e)}} — {{e.port_key}}</option></select></label><label>Search device, outlet, cable ID<input v-model="search" placeholder="e.g. WAN1, PP01, CAT6-001"></label></div>
<div v-if="traceStart" class="trace"><strong>Connected path</strong><p v-if="!traceRows.length">No recorded connection from this endpoint.</p><div v-for="(step,i) in traceRows" :key="i" class="trace-step">{{step}}</div><p v-if="traceTruncated" class="hint">Trace capped at 100 connections to prevent loops.</p></div>
<div v-if="search.trim()" class="search-results"><h3>Search matches</h3><p v-for="(hit,i) in searchHits" :key="i">{{hit}}</p><p v-if="!searchHits.length">No matches found in this building.</p></div></section>
</template>
</div>
</template>
<script setup lang="ts">
definePageMeta({middleware:'auth'})
const client=useSupabaseClient();const {isAdmin,refreshRole}=useAccess()
const error=ref(''),notice=ref(''),busy=ref(false),buildingId=ref(''),traceStart=ref(''),search=ref('')
const buildings=ref<any[]>([]),equipment=ref<any[]>([]),circuits=ref<any[]>([]),endpoints=ref<any[]>([]),links=ref<any[]>([]),switches=ref<any[]>([]),panels=ref<any[]>([]),outlets=ref<any[]>([]),permanent=ref<any[]>([])
const equipmentKinds=['router','firewall','ntd','odf','media_converter','other']
const endpointTypes=[{value:'switch',label:'Switch'},{value:'patch_panel',label:'Patch panel'},{value:'outlet',label:'Wall outlet'},{value:'equipment',label:'Router / Firewall / NTD / ODF'},{value:'provider',label:'Provider circuit'}]
const media=['cat5e','cat6','cat6a','os2','om3','om4','om5','dac','other']
const blankEquipment=()=>({id:'',name:'',kind:'router',manufacturer:'',model:'',management_ip:'',notes:''})
const blankCircuit=()=>({id:'',provider:'',circuit_id:'',service_type:'fibre',handoff:'',notes:''})
const blankEndpoint=()=>({id:'',endpoint_type:'switch',ref_id:'',port_key:'',connector:'RJ45',notes:''})
const blankLink=()=>({id:'',a_id:'',b_id:'',medium:'cat6a',connection_kind:'patch_lead',cable_id:'',connector:'',fibre_cores:'',notes:''})
const equipmentForm=ref(blankEquipment()),circuitForm=ref(blankCircuit()),endpointForm=ref(blankEndpoint()),linkForm=ref(blankLink())
const localEquipment=computed(()=>equipment.value.filter(x=>x.building_id===buildingId.value))
const localCircuits=computed(()=>circuits.value.filter(x=>x.building_id===buildingId.value))
const localEndpoints=computed(()=>endpoints.value.filter(x=>x.building_id===buildingId.value))
const localLinks=computed(()=>links.value.filter(x=>x.building_id===buildingId.value))
const localPermanent=computed(()=>permanent.value.filter(x=>panels.value.some(p=>p.id===x.panel_id&&p.building_id===buildingId.value)))
function availableDevices(t:string){if(t==='switch')return switches.value.filter(x=>x.building_id===buildingId.value).map(x=>({id:x.id,name:x.name}));if(t==='patch_panel')return panels.value.filter(x=>x.building_id===buildingId.value).map(x=>({id:x.id,name:x.name}));if(t==='outlet')return outlets.value.filter(x=>x.building_id===buildingId.value).map(x=>({id:x.id,name:x.label}));if(t==='equipment')return localEquipment.value.map(x=>({id:x.id,name:x.name}));return localCircuits.value.map(x=>({id:x.id,name:`${x.provider} / ${x.circuit_id||'Service'}`}))}
function endpointLabel(e:any){return availableDevices(e.endpoint_type).find(x=>x.id===e.ref_id)?.name||`${e.endpoint_type} (missing)`}
function endpointText(id:string){const e=endpoints.value.find(x=>x.id===id);return e?`${endpointLabel(e)} — ${e.port_key}`:'Unknown endpoint'}
function linked(id:string,except=''){return localLinks.value.some(x=>x.id!==except&&(x.a_id===id||x.b_id===id))}
watch(buildingId,()=>{equipmentForm.value=blankEquipment();circuitForm.value=blankCircuit();endpointForm.value=blankEndpoint();linkForm.value=blankLink();traceStart.value=''})
async function reload(){error.value='';const tables=['buildings','network_equipment','provider_circuits','physical_endpoints','physical_links','network_switches','patch_panels','network_outlets','cable_links'];const results=await Promise.all(tables.map(t=>client.from(t).select('*')));const bad=results.find(r=>r.error);if(bad?.error)error.value=`${bad.error.message} — ensure migration 005 has been applied.`;[buildings.value,equipment.value,circuits.value,endpoints.value,links.value,switches.value,panels.value,outlets.value,permanent.value]=results.map(r=>r.data||[]);if(!buildings.value.some(b=>b.id===buildingId.value))buildingId.value=buildings.value[0]?.id||''}
async function run(action:()=>Promise<any>,message:string,reset:()=>void){if(!isAdmin.value||busy.value)return;busy.value=true;error.value='';notice.value='';try{const result=await action();if(result.error)throw result.error;reset();await reload();notice.value=message}catch(e:any){error.value=e.message||String(e)}finally{busy.value=false}}
function saveEquipment(){const f=equipmentForm.value;const data={building_id:buildingId.value,name:f.name.trim(),kind:f.kind,manufacturer:f.manufacturer,model:f.model,management_ip:f.management_ip,notes:f.notes};run(()=>f.id?client.from('network_equipment').update(data).eq('id',f.id):client.from('network_equipment').insert(data),'Equipment saved.',()=>equipmentForm.value=blankEquipment())}
function saveCircuit(){const f=circuitForm.value;const data={building_id:buildingId.value,provider:f.provider.trim(),circuit_id:f.circuit_id,service_type:f.service_type,handoff:f.handoff,notes:f.notes};run(()=>f.id?client.from('provider_circuits').update(data).eq('id',f.id):client.from('provider_circuits').insert(data),'Circuit saved.',()=>circuitForm.value=blankCircuit())}
function saveEndpoint(){const f=endpointForm.value;const data={building_id:buildingId.value,endpoint_type:f.endpoint_type,ref_id:f.ref_id,port_key:f.port_key.trim(),connector:f.connector,notes:f.notes};run(()=>f.id?client.from('physical_endpoints').update(data).eq('id',f.id):client.from('physical_endpoints').insert(data),'Endpoint saved.',()=>endpointForm.value=blankEndpoint())}
function saveLink(){const f=linkForm.value;if(f.a_id===f.b_id){error.value='Select two different endpoints.';return}const data={building_id:buildingId.value,a_id:f.a_id,b_id:f.b_id,medium:f.medium,connection_kind:f.connection_kind,cable_id:f.cable_id,connector:f.connector,fibre_cores:f.fibre_cores,notes:f.notes};run(()=>f.id?client.from('physical_links').update(data).eq('id',f.id):client.from('physical_links').insert(data),'Link saved.',()=>linkForm.value=blankLink())}
function removeEquipment(e:any){if(confirm(`Delete ${e.name}? Delete its endpoints first.`))run(()=>client.from('network_equipment').delete().eq('id',e.id),'Equipment deleted.',()=>{})}
function removeCircuit(c:any){if(confirm(`Delete ${c.provider} circuit? Delete its endpoints first.`))run(()=>client.from('provider_circuits').delete().eq('id',c.id),'Circuit deleted.',()=>{})}
function removeEndpoint(e:any){if(confirm(`Delete ${endpointText(e.id)} and attached physical links?`))run(()=>client.from('physical_endpoints').delete().eq('id',e.id),'Endpoint deleted.',()=>{})}
function removeLink(l:any){if(confirm('Delete this physical cable link?'))run(()=>client.from('physical_links').delete().eq('id',l.id),'Link deleted.',()=>{})}
// A patch-panel has two distinct termination faces: front:N is a patch lead,
// rear:N is the existing permanent cable, linked internally by the panel port.
const graph=computed(()=>{const adj=new Map<string,{to:string,label:string}[]>();function edge(a:string,b:string,label:string){if(!adj.has(a))adj.set(a,[]);if(!adj.has(b))adj.set(b,[]);adj.get(a)!.push({to:b,label});adj.get(b)!.push({to:a,label})}
for(const l of localLinks.value)edge(l.a_id,l.b_id,`${l.connection_kind} · ${l.medium.toUpperCase()}${l.cable_id?' · '+l.cable_id:''}`)
for(const l of localPermanent.value){const front=localEndpoints.value.find(e=>e.endpoint_type==='patch_panel'&&e.ref_id===l.panel_id&&e.port_key===`front:${l.panel_port}`);const rear=localEndpoints.value.find(e=>e.endpoint_type==='patch_panel'&&e.ref_id===l.panel_id&&e.port_key===`rear:${l.panel_port}`);const outlet=localEndpoints.value.find(e=>e.endpoint_type==='outlet'&&e.ref_id===l.outlet_id&&e.port_key===String(l.outlet_socket));if(front&&rear)edge(front.id,rear.id,'Patch-panel internal termination');if(rear&&outlet)edge(rear.id,outlet.id,`Permanent cable${l.cable_id?' · '+l.cable_id:''}`)}return adj})
const traceTruncated=ref(false)
const traceRows=computed(()=>{traceTruncated.value=false;if(!traceStart.value)return [];const seen=new Set([traceStart.value]);const queue=[traceStart.value];const out:string[]=[];while(queue.length&&out.length<100){const a=queue.shift()!;for(const edge of graph.value.get(a)||[]){if(seen.has(edge.to))continue;seen.add(edge.to);queue.push(edge.to);out.push(`${endpointText(a)} → ${endpointText(edge.to)} (${edge.label})`);if(out.length>=100)break}}traceTruncated.value=queue.length>0;return out})
const searchHits=computed(()=>{const q=search.value.trim().toLowerCase();if(!q)return [];return [...localEndpoints.value.filter(e=>`${endpointText(e.id)} ${e.connector} ${e.notes}`.toLowerCase().includes(q)).map(e=>`Port: ${endpointText(e.id)}`),...localLinks.value.filter(l=>`${l.cable_id} ${l.notes} ${endpointText(l.a_id)} ${endpointText(l.b_id)}`.toLowerCase().includes(q)).map(l=>`Cable: ${endpointText(l.a_id)} → ${endpointText(l.b_id)} (${l.cable_id||l.medium})`),...localPermanent.value.filter(l=>`${l.cable_id} ${l.notes}`.toLowerCase().includes(q)).map(l=>`Permanent cable: ${l.cable_id||'Unlabelled'}`)].slice(0,60)})
onMounted(async()=>{await refreshRole();await reload()})
</script>
<style scoped>
.connectivity{display:grid;gap:18px}.top{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}.top p,.hint{color:#65758a}.toolbar{display:flex;align-items:end;gap:12px}.toolbar label{flex:1}.twocol{display:grid;grid-template-columns:1fr 1fr;gap:18px;align-items:start}.formgrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:15px 0}.formgrid label,.endpoint-form label,.link-form label,.toolbar label,.trace-tools label{display:grid;gap:5px;min-width:0}.wide,.actions{grid-column:1/-1}.actions{display:flex;gap:8px;flex-wrap:wrap}.record{border-top:1px solid #dbe2eb;padding:12px 0;display:flex;align-items:center;gap:10px;flex-wrap:wrap}.record span{color:#66758b;font-size:.85rem;margin-right:auto}.endpoint-form,.link-form{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;align-items:end;margin:16px 0}.scroll{overflow-x:auto}table{width:100%;border-collapse:collapse;text-align:left}td,th{padding:10px;border-bottom:1px solid #dbe2eb}th{white-space:nowrap}.trace-tools{display:grid;grid-template-columns:1fr 1fr;gap:12px}.trace{background:#eef4fa;padding:15px;border-radius:8px;margin-top:14px}.trace-step{padding:9px;border-left:3px solid #4b789a;margin-top:7px;background:white;overflow-wrap:anywhere}.warning{color:#a11}.ok{color:#17653a}.search-results{margin-top:12px}@media(max-width:1000px){.twocol{grid-template-columns:1fr}.endpoint-form,.link-form{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.endpoint-form,.link-form,.formgrid,.trace-tools{grid-template-columns:1fr}}
</style>
